"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/breakdown.css";
import type { CSSProperties, HTMLAttributes, ReactNode } from "react";
import { formatAnalyticsValue } from "../../lib/analytics";
import { cn } from "../../lib/cn";

export type BreakdownItem = {
  id: string;
  label: string;
  value: number;
  detail?: ReactNode;
  tone?: "primary" | "secondary" | "tertiary";
};

export type BreakdownProps = Omit<HTMLAttributes<HTMLOListElement>, "onSelect"> & {
  label: string;
  items: readonly BreakdownItem[];
  formatter?: (value: number, item: BreakdownItem) => string;
  max?: number;
  selectedId?: string;
  onSelect?: (item: BreakdownItem) => void;
};

export function Breakdown({ label, items, formatter = (value) => formatAnalyticsValue(value), max, selectedId, onSelect, className, ...props }: BreakdownProps) {
  const maximum = Math.max(1, max ?? Math.max(0, ...items.map((item) => item.value)));
  return (
    <ol className={cn("whatiuse-breakdown", className)} aria-label={label} {...props}>
      {items.map((item) => {
        const ratio = Math.min(1, Math.max(0, item.value / maximum));
        const content = <>
          <span className="whatiuse-breakdown__label">{item.label}</span>
          <span className="whatiuse-breakdown__bar" aria-hidden="true"><span data-tone={item.tone ?? "primary"} style={{ "--whatiuse-breakdown-progress": ratio } as CSSProperties} /></span>
          <strong>{formatter(item.value, item)}</strong>
          {item.detail && <small>{item.detail}</small>}
        </>;
        return <li key={item.id}>{onSelect ? <button type="button" aria-pressed={item.id === selectedId} onClick={() => onSelect(item)}>{content}</button> : <div>{content}</div>}</li>;
      })}
    </ol>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-breakdown { display: grid; min-width: 0; gap: 2px; margin: 0; padding: 0; list-style: none; }

.whatiuse-breakdown li > div,
.whatiuse-breakdown li > button { display: grid; width: 100%; min-height: 36px; grid-template-columns: minmax(0, 1fr) minmax(56px, .72fr) auto; align-items: center; gap: 10px; padding: 5px 6px; border: 0; border-radius: var(--whatiuse-radius-control); background: transparent; color: inherit; font: inherit; text-align: left; }

.whatiuse-breakdown li > button { cursor: pointer; }

.whatiuse-breakdown__label { overflow: hidden; color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-ui); text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-breakdown__bar { height: 4px; overflow: hidden; border-radius: 999px; background: var(--whatiuse-bg-subtle); }

.whatiuse-breakdown__bar > span { display: block; width: calc(var(--whatiuse-breakdown-progress) * 100%); height: 100%; border-radius: inherit; background: var(--whatiuse-fg-default); }

.whatiuse-breakdown__bar > span[data-tone="secondary"] { opacity: .58; }

.whatiuse-breakdown__bar > span[data-tone="tertiary"] { opacity: .34; }

.whatiuse-breakdown strong { min-width: 46px; text-align: right; font-size: var(--whatiuse-type-ui); font-variant-numeric: tabular-nums; font-weight: 570; }

.whatiuse-breakdown small { grid-column: 1 / -1; color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); }

.whatiuse-breakdown li > button:focus { outline: 0; }

.whatiuse-breakdown li > button:focus-visible {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--whatiuse-focus-control) 42%, transparent);
}

@media (hover: hover) and (pointer: fine) {
.whatiuse-breakdown li > button:hover { background: var(--whatiuse-hover); color: var(--whatiuse-fg-default); }
}

.whatiuse-breakdown li > button:active { transform: scale(.985); }

.whatiuse-breakdown li > button[aria-pressed="true"] { background: var(--whatiuse-selected); }

@media (max-width: 640px) {
.whatiuse-breakdown li > div,
.whatiuse-breakdown li > button { grid-template-columns: minmax(86px, .8fr) minmax(54px, 1fr) auto; gap: 7px; }
}
}
